/* =============================================
   Wedding website — main.js
   ============================================= */

'use strict';

// ---------------------------------------------------------------------------
// CONFIG — every wedding fact comes from js/config.js (see config.example.js).
// The deployed config.js is generated by setup/build.js and never contains
// the invitation code itself, only AUTH (a PBKDF2 salt + key check).
// ---------------------------------------------------------------------------
const _private = window.SITE_CONFIG || {};
const CONFIG = {
  AUTH:          _private.AUTH || null,
  WEDDING_DATE:  _private.WEDDING_DATE || '2027-01-01T16:00:00-05:00',
  OPEN_WINDOW:   _private.OPEN_WINDOW || null,
  DAY_OF_BUTTON: _private.DAY_OF_BUTTON || null,
  WELCOME:       _private.WELCOME || {},
};

// Detect reduced-motion preference once
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Shared helpers (also used by rsvp-upgrade.js and the examples through
// window.WeddingSite, so there's one copy of each).
function escHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Keep Tab / Shift+Tab cycling inside a dialog while focus is in it.
function trapFocus(container) {
  container.addEventListener('keydown', e => {
    if (e.key !== 'Tab') return;
    const els = Array.from(container.querySelectorAll('a[href], button, input, select, textarea'))
      .filter(el => !el.disabled && !el.closest('[hidden]'));
    if (!els.length) return;
    const first = els[0];
    const last  = els[els.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });
}

// ---------------------------------------------------------------------------
// SITE CONTENT — fills every element tagged data-field="..." with the
// matching value from config.js, and sets the page <title>, so couple
// names / venue / date / contact info are defined once and reused
// everywhere instead of being typed out on every page.
// ---------------------------------------------------------------------------
function applySiteContent() {
  const fields = {
    coupleNames: _private.COUPLE_NAMES,
    weddingDateDisplay: _private.WEDDING_DATE_DISPLAY,
    venueName: _private.VENUE_NAME,
    venueCity: _private.VENUE_CITY,
    dressCode: _private.DRESS_CODE,
    hashtag: _private.HASHTAG,
    contactEmail: _private.CONTACT_EMAIL,
  };

  // data-field="weddingDateDisplay" (the names above), or any key you add
  // to config.js as-is: data-field="BRUNCH_TIME"
  document.querySelectorAll('[data-field]').forEach(el => {
    const key   = el.dataset.field;
    const value = key in fields ? fields[key] : _private[key];
    if (typeof value === 'string' || typeof value === 'number') el.textContent = value;
  });

  document.querySelectorAll('[data-href-field]').forEach(el => {
    const key = el.dataset.hrefField;
    if (key === 'contactEmail' && fields.contactEmail) {
      el.href = `mailto:${fields.contactEmail}`;
    } else if (key === 'map') {
      // "Get Directions": a maps search for the venue's name and address
      const where = [_private.VENUE_NAME, _private.VENUE_ADDRESS || _private.VENUE_CITY].filter(Boolean).join(', ');
      if (where) el.href = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(where)}`;
    } else if (key === 'whatsapp') {
      // No WhatsApp link configured: hide the link (and the dot before it)
      // rather than leave a dead "#".
      if (_private.WHATSAPP_LINK) el.href = _private.WHATSAPP_LINK;
      else (el.closest('[data-hide-without-whatsapp]') || el).hidden = true;
    }
  });

  if (fields.coupleNames) {
    document.title = document.title.replace('{{COUPLE_NAMES}}', fields.coupleNames);
  }
}
document.addEventListener('DOMContentLoaded', applySiteContent);

// ---------------------------------------------------------------------------
// AUTH — one invitation code for the whole site.
//
// The code is stretched with PBKDF2 (salt + iterations from config.js) into
// a 256-bit key. sha256(key) must match AUTH.check; the same key decrypts
// the guest list (js/guests.js, sealed by setup/build.js). The key, not the
// code, is remembered in localStorage so guests who only ever used their QR
// link stay unlocked after closing the tab.
//
// This is a soft gate: page text is still in the HTML for anyone who views
// source. What it really protects is the guest list. See SECURITY.md.
// ---------------------------------------------------------------------------
const KEY_STORAGE = 'wedding_key';

const enc = new TextEncoder();
const toHex   = buf => Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
const fromHex = hex => new Uint8Array((hex.match(/../g) || []).map(h => parseInt(h, 16)));
const fromB64 = b64 => Uint8Array.from(atob(b64), c => c.charCodeAt(0));

function storageGet(k)    { try { return localStorage.getItem(k); } catch (e) { return null; } }
function storageSet(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode: unlock lasts this visit */ } }

async function deriveKey(password) {
  const base = await crypto.subtle.importKey('raw', enc.encode(password.normalize('NFC')), 'PBKDF2', false, ['deriveBits']);
  return crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt: enc.encode(CONFIG.AUTH.salt), iterations: CONFIG.AUTH.iterations, hash: 'SHA-256' },
    base, 256
  );
}

async function keyIsValid(raw) {
  if (!CONFIG.AUTH || !raw) return false;
  return toHex(await crypto.subtle.digest('SHA-256', raw)) === CONFIG.AUTH.check;
}

// Returns the key for a correct code (and remembers it), or null.
async function keyFromPassword(password) {
  if (!CONFIG.AUTH || !password) return null;
  const raw = await deriveKey(password);
  if (!(await keyIsValid(raw))) return null;
  storageSet(KEY_STORAGE, toHex(raw));
  return raw;
}

// Returns the remembered key if it still opens this site, or null.
// (Changing the code changes the key, which signs everyone out.)
async function keyFromStorage() {
  const hex = storageGet(KEY_STORAGE);
  if (!hex) return null;
  const raw = fromHex(hex).buffer;
  return (await keyIsValid(raw)) ? raw : null;
}

async function openGuestList(raw) {
  const sealed = window.GUEST_LIST_SEALED;
  if (!sealed || !raw) return null;
  try {
    const key   = await crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['decrypt']);
    const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: fromB64(sealed.iv) }, key, fromB64(sealed.data));
    return JSON.parse(new TextDecoder().decode(plain));
  } catch (e) {
    console.error('Could not open the guest list:', e);
    return null;
  }
}

function findGuest(list, name) {
  if (!list || !name) return null;
  const q = name.toLowerCase().trim();
  return list.find(g => g.name.toLowerCase().trim() === q) || null;
}

// Shared with js/rsvp-upgrade.js. The guest list arrives asynchronously
// (decryption), possibly late (a guest unlocks from the RSVP section during
// the open window), so the RSVP code subscribes instead of reading a global.
const WeddingSite = (function () {
  const listeners = [];
  let guests;            // undefined = still working it out, null = locked
  return {
    invitedGuest: null,  // the guest named in a valid personal link
    escHtml,
    trapFocus,
    get guests() { return guests; },
    onGuests(fn) { listeners.push(fn); if (guests !== undefined) fn(guests); },
    setGuests(list) { guests = list; listeners.forEach(fn => fn(list)); },
    async unlock(password) {
      const raw = await keyFromPassword(password);
      if (!raw) return false;
      this.setGuests(await openGuestList(raw));
      return true;
    },
  };
})();
window.WeddingSite = WeddingSite;

// The whole site opens without the code during CONFIG.OPEN_WINDOW (the
// wedding weekend). Nothing is saved, so the gate is back afterwards.
function inWindow(w) {
  if (!w) return false;
  const now = Date.now();
  return now >= Date.parse(w.from) && now < Date.parse(w.until);
}

// Take the code (and name) out of the address bar once they've been used,
// so it isn't shared when a guest copies the link or takes a screenshot.
function stripInviteParams() {
  const url = new URL(window.location.href);
  if (!url.searchParams.has('pw') && !url.searchParams.has('name')) return;
  url.searchParams.delete('pw');
  url.searchParams.delete('name');
  history.replaceState(null, '', url.pathname + url.search + url.hash);
}

// ---------------------------------------------------------------------------
// PASSWORD GATE — every page with a #password-gate is gated; pages without
// one (e.g. a short-link redirect) are public.
// ---------------------------------------------------------------------------
async function initPasswordGate() {
  const gate    = document.getElementById('password-gate');
  const params  = new URLSearchParams(window.location.search);
  const urlName = (params.get('name') || '').trim();
  const urlPw   = (params.get('pw')   || '').trim();

  // 1. Personal / QR link (?name=...&pw=...), or a code-only link (?pw=...)
  if (urlPw) {
    const raw = await keyFromPassword(urlPw);
    if (raw) {
      stripInviteParams();
      const list = await openGuestList(raw);
      const guest = findGuest(list, urlName);
      WeddingSite.invitedGuest = guest;
      WeddingSite.setGuests(list);
      if (urlName && gate && list) {
        if (guest) showWelcome(guest, gate);
        else showGateNotFound(gate);   // right code, name not on the list
        return;
      }
      unlockSite(gate);
      return;
    }
  }

  // 2. Already unlocked on this device
  const stored = await keyFromStorage();
  if (stored) {
    WeddingSite.setGuests(await openGuestList(stored));
    unlockSite(gate);
    return;
  }

  // 3. Wedding weekend: open without a code (the guest list stays locked)
  if (inWindow(CONFIG.OPEN_WINDOW) || !gate) {
    WeddingSite.setGuests(null);
    unlockSite(gate);
    return;
  }

  WeddingSite.setGuests(null);
  showGate(gate, urlName);
}

function showGate(gate, pendingName) {
  const form    = document.getElementById('gate-form');
  const input   = document.getElementById('gate-input');
  const errorEl = document.getElementById('gate-error');
  const button  = form.querySelector('button[type="submit"]');

  document.body.classList.add('gate-visible');

  trapFocus(gate);

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errorEl.textContent = '';

    const val = input.value.trim();
    if (!val) { errorEl.textContent = 'Please enter the invitation code.'; return; }

    // Key stretching takes a moment on older phones
    const label = button ? button.textContent : '';
    if (button) { button.disabled = true; button.textContent = 'Checking…'; }
    const ok = await WeddingSite.unlock(val);
    if (button) { button.disabled = false; button.textContent = label; }

    if (!ok) {
      errorEl.textContent = 'Incorrect code. Please try again.';
      input.value = '';
      input.focus();
      return;
    }

    // Arrived with ?name= but no (or a wrong) code: welcome them by name now
    stripInviteParams();
    const guest = findGuest(WeddingSite.guests, pendingName);
    if (guest) {
      WeddingSite.invitedGuest = guest;
      showWelcome(guest, gate);
    } else {
      unlockSite(gate);
    }
  });
}

function unlockSite(gate) {
  document.body.classList.remove('gate-visible');
  if (!gate || !gate.isConnected) return;
  gate.classList.add('hidden');
  // Remove from DOM after transition to prevent tab-focus issues
  gate.addEventListener('transitionend', () => gate.remove(), { once: true });
  setTimeout(() => gate.remove(), 1000); // reduced motion: no transitionend
}

function showGateNotFound(gate) {
  const form    = gate.querySelector('#gate-form');
  const prompt  = gate.querySelector('.gate-prompt');
  const errorEl = gate.querySelector('#gate-error');
  if (form)    form.hidden   = true;
  if (prompt)  prompt.hidden = true;
  if (errorEl) errorEl.hidden = true;

  const card = gate.querySelector('.gate-card');

  const msg = document.createElement('p');
  msg.className   = 'gate-not-found';
  msg.textContent = "We weren't able to find your name on our guest list. Your link may have a small error. You're still welcome to enter the site and search for your name when you RSVP.";
  card?.appendChild(msg);

  const enterBtn = document.createElement('button');
  enterBtn.type      = 'button';
  enterBtn.className = 'gate-btn gate-btn--ghost';
  enterBtn.textContent = 'Enter the site';
  enterBtn.addEventListener('click', () => unlockSite(gate));
  card?.appendChild(enterBtn);

  document.body.classList.add('gate-visible');
}

// ---------------------------------------------------------------------------
// PERSONALIZED WELCOME CARD — shown for a valid ?name=...&pw=... link.
// Wording, schedule and buttons come from CONFIG.WELCOME; a guest with a
// `group` in guests.js gets that group's overrides (WELCOME.groups).
// ---------------------------------------------------------------------------
function welcomeFor(guest) {
  const base  = CONFIG.WELCOME || {};
  const group = (guest.group && base.groups && base.groups[guest.group]) || {};
  return {
    message:  group.message  ?? base.message ?? 'Together with our families, we joyfully invite you to join us in celebrating our union.',
    schedule: group.schedule ?? base.schedule ?? [],
    buttons:  group.buttons  ?? base.buttons ?? [{ label: 'RSVP', href: '#rsvp', variant: 'primary' }],
  };
}

function showWelcome(guest, gate) {
  // Hide password gate — welcome overlay takes over
  gate.style.display = 'none';
  document.body.classList.remove('gate-visible');

  const w = welcomeFor(guest);

  const scheduleHtml = w.schedule.length ? `
      <div class="welcome-timeline">
        ${w.schedule.map(s => `
        <div class="welcome-tl-slot">
          <span class="welcome-tl-event">${escHtml(s.event)}</span>
          <span class="welcome-tl-time">${escHtml(s.time)}</span>
        </div>`).join('')}
      </div>` : '';

  // External links open in a new tab so guests don't lose the wedding site
  const buttonsHtml = w.buttons.map(b => {
    const external = /^https?:\/\//.test(b.href);
    const attrs = external ? ' target="_blank" rel="noopener"' : '';
    return `<a href="${escHtml(b.href)}" class="welcome-btn welcome-btn--${b.variant === 'primary' ? 'primary' : 'secondary'}"${attrs}>${escHtml(b.label)}</a>`;
  }).join('\n        ');

  const overlay = document.createElement('div');
  overlay.id = 'welcome-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-label', 'You are invited');
  overlay.innerHTML = `
    <div class="welcome-card">
      <button type="button" class="welcome-close" aria-label="Close and enter site">&times;</button>
      <p class="gate-script">${escHtml(_private.COUPLE_NAMES || '')}</p>
      <h1 class="welcome-title">You're Invited</h1>
      <p class="welcome-message">${escHtml(w.message)}</p>
      <p class="welcome-name-label">Welcome,</p>
      <p class="welcome-name" aria-live="polite"></p>
      <p class="welcome-subtitle">${escHtml(_private.WEDDING_DATE_DISPLAY || '')}</p>
      <p class="welcome-venue">${escHtml(_private.VENUE_NAME || '')}</p>
      ${scheduleHtml}
      <div class="welcome-actions">
        ${buttonsHtml}
      </div>
      ${_private.DRESS_CODE ? `<p class="welcome-dresscode">Dress code: ${escHtml(_private.DRESS_CODE)}</p>` : ''}
    </div>
  `;
  document.body.appendChild(overlay);

  // Typewriter animation for the guest's name, exactly as it is in the
  // guest list (shortening long names read as a mistake to guests).
  const nameEl  = overlay.querySelector('.welcome-name');
  const display = guest.name;
  let i = 0;
  nameEl.textContent = '';
  nameEl.classList.add('typing');

  const type = () => {
    if (i < display.length) {
      nameEl.textContent += display[i++];
      setTimeout(type, prefersReducedMotion ? 0 : 70);
    } else {
      nameEl.classList.remove('typing');
    }
  };
  setTimeout(type, 600); // short pause before typing starts

  // Dismiss overlay — optionally scroll to a target section after
  const dismiss = (scrollTo) => {
    overlay.classList.add('hidden');
    const done = () => {
      if (!overlay.isConnected) return;
      overlay.remove();
      if (scrollTo) {
        const el = document.getElementById(scrollTo);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    };
    overlay.addEventListener('transitionend', done, { once: true });
    setTimeout(done, 1000);
    gate.remove();
  };
  // CTA buttons navigate via their href — just dismiss the overlay
  overlay.querySelectorAll('.welcome-btn').forEach(btn => btn.addEventListener('click', () => dismiss()));
  // X button → return to hero, not RSVP
  overlay.querySelector('.welcome-close')?.addEventListener('click', () => dismiss('hero'));
}

// ---------------------------------------------------------------------------
// NAVBAR
// ---------------------------------------------------------------------------
function initNavbar() {
  const navbar = document.getElementById('navbar');
  const toggle = document.getElementById('nav-toggle');
  const links  = document.getElementById('nav-links');
  // Pages without a nav: without this guard the error stopped every init
  // after this one (countdown, reveal) from running.
  if (!navbar || !toggle || !links) return;
  const navAnchors = links.querySelectorAll('a');

  const onScroll = () => {
    navbar.classList.toggle('scrolled', window.scrollY > 60);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  toggle.addEventListener('click', () => {
    const open = links.classList.toggle('open');
    toggle.setAttribute('aria-expanded', String(open));
  });

  navAnchors.forEach(a => {
    a.addEventListener('click', () => {
      links.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
    });
  });
}

// ---------------------------------------------------------------------------
// HERO parallax + bg load
// ---------------------------------------------------------------------------
function initHero() {
  const bg = document.querySelector('.hero-bg');
  if (bg) {
    // Trigger the subtle zoom-out after page load
    requestAnimationFrame(() => bg.classList.add('loaded'));

    // Subtle parallax — disabled when user requests reduced motion
    if (!prefersReducedMotion) {
      window.addEventListener('scroll', () => {
        const y = window.scrollY;
        if (y < window.innerHeight) {
          bg.style.transform = `scale(1) translateY(${y * 0.25}px)`;
        }
      }, { passive: true });
    }
  }

  // Fade in hero content
  document.querySelectorAll('.hero-content, .page-hero-content').forEach(el => {
    setTimeout(() => el.classList.add('visible'), prefersReducedMotion ? 0 : 200);
  });
}

// ---------------------------------------------------------------------------
// ADD TO CALENDAR — <a href="wedding.ics"> works on its own (the build
// writes one .ics per event); this fills in the Google Calendar links:
// <a data-google-calendar="wedding"> or the key of an EVENTS entry.
// ---------------------------------------------------------------------------
function calendarEvent(key) {
  if (key === 'wedding') {
    return {
      title: `${_private.COUPLE_NAMES || ''}'s Wedding`,
      start: CONFIG.WEDDING_DATE, end: _private.WEDDING_END,
      location: [_private.VENUE_NAME, _private.VENUE_ADDRESS || _private.VENUE_CITY].filter(Boolean).join(', '),
    };
  }
  return (_private.EVENTS || []).find(e => e.key === key) || null;
}

function initCalendarLinks() {
  const stamp = t => new Date(t).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  document.querySelectorAll('[data-google-calendar]').forEach(a => {
    const e = calendarEvent(a.dataset.googleCalendar);
    if (!e || Number.isNaN(Date.parse(e.start))) { a.hidden = true; return; }
    const end = e.end ? Date.parse(e.end) : Date.parse(e.start) + 6 * 3600e3;
    a.href = 'https://calendar.google.com/calendar/render?' + new URLSearchParams({
      action: 'TEMPLATE', text: e.title || '', dates: `${stamp(e.start)}/${stamp(end)}`,
      location: e.location || '', details: _private.SITE_URL || '',
    });
  });
}

// ---------------------------------------------------------------------------
// DAY-OF BUTTON — optional floating button on the home page during a time
// window (CONFIG.DAY_OF_BUTTON), e.g. "Today's Program" on the wedding day.
// Re-checked every minute so it appears on its own if the page is open at
// midnight. No code in the link: the same invitation code opens every page.
// ---------------------------------------------------------------------------
function initDayOfButton() {
  const cfg = CONFIG.DAY_OF_BUTTON;
  if (!cfg || !document.getElementById('hero')) return; // home page only

  let btn = null;
  function check() {
    const show = inWindow(cfg);
    if (show && !btn) {
      btn = document.createElement('a');
      btn.href        = cfg.href;
      btn.className   = 'day-of-program-btn';
      btn.textContent = cfg.label || "Today's Program";
      document.body.appendChild(btn);
    } else if (!show && btn) {
      btn.remove();
      btn = null;
    }
  }
  check();
  setInterval(check, 60000);
}

// ---------------------------------------------------------------------------
// COUNTDOWN TIMER
// ---------------------------------------------------------------------------
function initCountdown(prefix, date) {
  prefix = prefix || 'cd-';
  const target = new Date(date || CONFIG.WEDDING_DATE).getTime();

  const daysEl    = document.getElementById(prefix + 'days');
  const hoursEl   = document.getElementById(prefix + 'hours');
  const minutesEl = document.getElementById(prefix + 'minutes');
  const secondsEl = document.getElementById(prefix + 'seconds');

  if (!daysEl) return;

  function tick() {
    const now  = Date.now();
    const diff = target - now;

    if (diff <= 0) {
      daysEl.textContent = hoursEl.textContent = minutesEl.textContent = secondsEl.textContent = '00';
      return;
    }

    const days    = Math.floor(diff / 86400000);
    const hours   = Math.floor((diff % 86400000) / 3600000);
    const minutes = Math.floor((diff % 3600000)  / 60000);
    const seconds = Math.floor((diff % 60000)    / 1000);

    daysEl.textContent    = String(days).padStart(2, '0');
    hoursEl.textContent   = String(hours).padStart(2, '0');
    minutesEl.textContent = String(minutes).padStart(2, '0');
    secondsEl.textContent = String(seconds).padStart(2, '0');
  }

  tick();
  setInterval(tick, 1000);
}

// ---------------------------------------------------------------------------
// SCROLL REVEAL (Intersection Observer)
// ---------------------------------------------------------------------------
function initReveal() {
  // Skip animation for users who prefer reduced motion — show everything immediately
  if (prefersReducedMotion) {
    document.querySelectorAll('.reveal').forEach(el => el.classList.add('visible'));
    return;
  }

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const delay = (entry.target.dataset.delay || 0);
          setTimeout(() => entry.target.classList.add('visible'), delay);
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.12 }
  );

  // Stagger cards within a grid/list
  document.querySelectorAll('.details-grid, .travel-grid').forEach(grid => {
    grid.querySelectorAll('.reveal').forEach((el, i) => {
      el.dataset.delay = i * 100;
    });
  });

  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
}

// ---------------------------------------------------------------------------
// BOOT
// ---------------------------------------------------------------------------
// FAQ uses native <details>/<summary> — no JS needed for the accordion.
document.addEventListener('DOMContentLoaded', () => {
  initPasswordGate();
  initNavbar();
  initHero();
  // A page for another event (welcome drinks, a brunch) counts down to its
  // own time: <div class="countdown-grid" data-countdown-date="2027-06-13T11:30:00-04:00">
  initCountdown('cd-', document.querySelector('[data-countdown-date]')?.dataset.countdownDate);
  initReveal();
  initDayOfButton();
  initCalendarLinks();
});
